sys_script_include.script:
var RegistrationValidatorAjax = Class.create();
RegistrationValidatorAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    initialize: function() {},

    hasAvailableBases: function() {
        var user = gs.getUserID();

        var regCheck = new GlideRecord("x_2060759_base_m_0_registration");
        regCheck.addEncodedQuery(
            "opened_by=" + user +
            "^baseISNOTEMPTY" +
            "^state!=4"
        );
        regCheck.setLimit(1);
        regCheck.query();

        if (regCheck.hasNext()) {
            return "false";
        }

        var base = new GlideRecord("x_2060759_base_m_0_bases");
        base.query();

        while (base.next()) {
            var maxCap = parseInt(base.getValue("maximum_capacity"), 10);
            var occCap = parseInt(base.getValue("occupied_capacity"), 10) || 0;

            if (!isNaN(maxCap) && maxCap > 0 && occCap < maxCap) {
                return "true";
            }
        }

        return "false";
    },

    type: "RegistrationValidatorAjax"
});
